-- Migration: Year 3 - Hematology/Oncology MCQ Bank (COMPLETE: 1-350)
-- Based on Harrison's 22nd Ed, Step-Up to Medicine 5th Ed, and Pocket Medicine 7th Ed.
-- This file is IDEMPOTENT: It deletes existing Heme/Onc MCQs before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'hematology-oncology' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1-9: ANEMIAS, COAGULATION, TRANSFUSION
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the most common cause of anemia worldwide?', '["Vitamin B12 deficiency", "Iron Deficiency Anemia", "Folate deficiency", "Sickle Cell"]', 1, 'Usually due to chronic blood loss or inadequate intake. (Harrison''s Ch. 93)'),
    (v_topic_id, '2: "Pica" (craving for non-food items like ice or dirt) and "Koilonychia" (spoon nails) are signs of:', '["Hemolysis", "Severe Iron Deficiency", "Lead poisoning", "Thalassemia"]', 1, 'Physical signs of chronic iron depletion. (Step-Up)'),
    (v_topic_id, '3: In Iron Deficiency Anemia, the Total Iron Binding Capacity (TIBC) is typically:', '["Low", "High", "Normal", "None"]', 1, 'The body produces more transferrin to capture any available iron. (Pocket Medicine)'),
    (v_topic_id, '4: What is the most common cause of iron deficiency in an elderly patient until proven otherwise?', '["Diet", "Gastrointestinal Malignancy/Blood loss", "Pregnancy", "Malabsorption"]', 1, 'Requires workup with Colonoscopy/EGD. (Harrison''s Ch. 93)'),
    (v_topic_id, '5: "Plummer-Vinson Syndrome" includes iron deficiency anemia, glossitis, and:', '["Esophageal webs", "Stomach cancer", "Diarrhea", "Leg cramps"]', 0, 'Associated with an increased risk of squamous cell esophageal cancer. (Step-Up)'),
    (v_topic_id, '6: "Anemia of Chronic Disease" is primarily mediated by which hormone/protein produced in the liver?', '["Erythropoietin", "Hepcidin", "Ferritin", "Albumin"]', 1, 'Hepcidin traps iron in macrophages and reduces absorption. (Pocket Medicine)'),
    (v_topic_id, '7: Unlike Iron Deficiency, Anemia of Chronic Disease typically has a ____ TIBC and a ____ Ferritin.', '["High; Low", "Low; Normal/High", "High; High", "Low; Low"]', 1, 'Iron stores are present but "trapped." (Harrison''s Ch. 93)'),
    (v_topic_id, '8: "Lead Poisoning" shows which classic finding on a peripheral blood smear?', '["Target cells", "Basophilic stippling", "Schistocytes", "Heinz bodies"]', 1, 'Due to inhibition of rRNA degradation. (Step-Up)'),
    (v_topic_id, '9: "Sideroblastic Anemia" is characterized by a failure to incorporate iron into heme. "Ringed sideroblasts" are found in the:', '["Peripheral blood", "Bone marrow", "Liver", "Spleen"]', 1, 'Iron-laden mitochondria encircling the nucleus. (Pocket Medicine)'),
    (v_topic_id, '10: "Mentzer Index" (MCV/RBC count) < 13 suggests ____, while > 13 suggests ____.', '["Iron deficiency; Thalassemia", "Thalassemia; Iron deficiency", "Hemolysis; Blood loss", "None"]', 1, 'Thalassemia has a high RBC count relative to the low MCV. (Harrison''s Ch. 93)'),
    (v_topic_id, '11: Alpha-thalassemia is primarily caused by gene ____, while Beta-thalassemia is caused by gene ____.', '["Mutation; Deletion", "Deletion; Mutation", "Duplication; Deletion", "None"]', 1, 'Alpha has 4 genes; Beta has 2. (Step-Up)'),
    (v_topic_id, '12: A patient with deletion of 3 alpha genes has "Hemoglobin H disease," which shows ____ on electrophoresis.', '["HbA2", "HbH (Beta-4 tetramers)", "HbF", "HbBart''s"]', 1, 'HbH is unstable and causes hemolysis. (Pocket Medicine)'),
    (v_topic_id, '13: "Hydrops Fetalis" occurs when ____ alpha genes are deleted.', '["One", "Two", "Three", "Four (Hb Bart''s)"]', 3, 'Incompatible with life; Gamma-4 tetramers have too high oxygen affinity. (Harrison''s Ch. 94)'),
    (v_topic_id, '14: "Beta-Thalassemia Major" (Cooley''s Anemia) becomes symptomatic at 6 months of life when ____ decreases.', '["HbA", "HbF (Fetal Hemoglobin)", "HbA2", "HbS"]', 1, 'Gamma chain production switches to Beta. (Step-Up)'),
    (v_topic_id, '15: "Chipmunk facies" and "Crew-cut" appearance on X-ray in Thalassemia are due to:', '["Infection", "Extramedullary hematopoiesis and marrow expansion", "Cancer", "Malnutrition"]', 1, 'The body is desperately trying to make more RBCs. (Pocket Medicine)'),
    (v_topic_id, '16: What is the most common cause of death in patients with Beta-Thalassemia Major receiving chronic transfusions?', '["Anemia", "Iron Overload (Hemochromatosis) causing heart failure", "Infection", "Stroke"]', 1, 'Requires aggressive iron chelation therapy. (Harrison''s Ch. 94)'),
    (v_topic_id, '17: Thalassemia peripheral smear classically shows which cell type?', '["Schistocytes", "Target cells", "Spherocytes", "Bite cells"]', 1, 'Due to relative membrane excess. (Step-Up)'),
    (v_topic_id, '18: "Hemoglobin A2" (Alpha-2, Delta-2) is elevated in which condition?', '["Alpha-thalassemia", "Beta-thalassemia minor", "Sickle cell", "Iron deficiency"]', 1, 'Used as a diagnostic marker on electrophoresis. (Pocket Medicine)'),
    (v_topic_id, '19: Patients with Thalassemia trait are often misdiagnosed as having:', '["B12 deficiency", "Iron Deficiency Anemia", "Leukemia", "None"]', 1, 'Both have low MCV, but Thalassemia has normal/high iron. (Harrison''s Ch. 94)'),
    (v_topic_id, '20: What is the definitive treatment for Thalassemia Major?', '["Iron pills", "Allogeneic Bone Marrow Transplant", "Splenectomy only", "Folate"]', 1, 'Can be curative in young patients. (Step-Up)'),
    (v_topic_id, '21: Megaloblastic anemia is characterized by which finding on a blood smear?', '["Target cells", "Hypersegmented Neutrophils (>5 lobes)", "Schistocytes", "Spherocytes"]', 1, 'Sign of impaired DNA synthesis. (Harrison''s Ch. 95)'),
    (v_topic_id, '22: Which vitamin deficiency causes megaloblastic anemia AND neurological symptoms (ataxia, paresthesias)?', '["Folate (B9)", "Vitamin B12 (Cobalamin)", "Vitamin C", "Vitamin D"]', 1, 'B12 is required for myelin maintenance. (Step-Up)'),
    (v_topic_id, '23: "Subacute Combined Degeneration" of the spinal cord in B12 deficiency involves the:', '["Anterior horns", "Dorsal columns and Lateral corticospinal tracts", "Occipital lobe", "Cerebellum"]', 1, 'Causes loss of vibration/position sense. (Pocket Medicine)'),
    (v_topic_id, '24: "Pernicious Anemia" is an autoimmune destruction of ____ cells in the stomach, leading to a lack of ____.', '["Goblet; Acid", "Parietal; Intrinsic Factor", "Chief; Pepsin", "Mucous; Bicarb"]', 1, 'Intrinsic factor is required for B12 absorption in the ileum. (Harrison''s Ch. 95)'),
    (v_topic_id, '25: "Folate deficiency" is most commonly seen in which population?', '["Athletes", "Chronic Alcoholics and Malnourished", "Children", "Elderly smokers"]', 1, 'Folate stores are small (only last 3-4 months). (Step-Up)'),
    (v_topic_id, '26: Which lab value is elevated in B12 deficiency but NORMAL in folate deficiency?', '["Homocysteine", "Methylmalonic Acid (MMA)", "Ferritin", "Bilirubin"]', 1, 'Specific marker for B12 metabolic pathway. (Pocket Medicine)'),
    (v_topic_id, '27: "Diphyllobothrium latum" (fish tapeworm) can cause deficiency of which vitamin?', '["Vitamin A", "Vitamin B12", "Vitamin E", "Vitamin K"]', 1, 'Competes with the host for B12 in the gut. (Harrison''s Ch. 95)'),
    (v_topic_id, '28: Large doses of Folate can "mask" a B12 deficiency by fixing the anemia but allowing ____ to progress.', '["Vision loss", "Neurological damage", "Liver failure", "Kidney failure"]', 1, 'Never treat macrocytic anemia with folate alone until B12 is checked. (Step-Up)'),
    (v_topic_id, '29: "Howell-Jolly bodies" in the blood suggest:', '["Iron deficiency", "Functional or surgical Asplenia", "Hemolysis", "B12 deficiency"]', 1, 'Nuclear remnants normally cleared by the spleen. (Pocket Medicine)'),
    (v_topic_id, '30: A "non-megaloblastic" macrocytic anemia (without hypersegmented neutrophils) can be seen in:', '["B12 deficiency", "Liver disease, Hypothyroidism, or Alcohol use", "Folate deficiency", "None"]', 1, 'Often due to lipid changes in the RBC membrane. (Harrison''s Ch. 95)'),
    (v_topic_id, '31: Which of the following is a sign of INTRAVASCULAR hemolysis?', '["Jaundice", "Hemoglobinuria and Low Haptoglobin", "Splenomegaly", "Gallstones"]', 1, 'Haptoglobin binds free hemoglobin released into the blood. (Step-Up)'),
    (v_topic_id, '32: "Hereditary Spherocytosis" is caused by a defect in RBC membrane proteins, most commonly:', '["Hemoglobin", "Ankyrin or Spectrin", "G6PD", "Iron"]', 1, 'Leads to spherical cells that are trapped in the spleen. (Pocket Medicine)'),
    (v_topic_id, '33: The screening test for Hereditary Spherocytosis is:', '["Coombs test", "Osmotic Fragility Test or EMA binding", "Electrophoresis", "Iron studies"]', 1, 'Spherocytes burst easily in hypotonic solutions. (Harrison''s Ch. 94)'),
    (v_topic_id, '34: What is the definitive treatment for symptomatic Hereditary Spherocytosis?', '["Iron", "Splenectomy", "Transfusion only", "Steroids"]', 1, 'Does not fix the cells but stops their destruction. (Step-Up)'),
    (v_topic_id, '35: "G6PD Deficiency" causes hemolysis when RBCs are exposed to:', '["Cold", "Oxidative stress (e.g., Fava beans, Sulfa drugs, Infection)", "Sugar", "Fat"]', 1, 'RBCs cannot regenerate glutathione to protect against ROS. (Pocket Medicine)'),
    (v_topic_id, '36: "Heinz bodies" and "Bite cells" on a smear are characteristic of:', '["Thalassemia", "G6PD Deficiency", "Sickle cell", "B12 deficiency"]', 1, 'Heinz bodies are precipitated hemoglobin; splenic macrophages "bite" them out. (Harrison''s Ch. 94)'),
    (v_topic_id, '37: "Paroxysmal Nocturnal Hemoglobinuria" (PNH) is due to a deficiency of:', '["Iron", "GPI-anchored proteins (CD55/CD59)", "Heme", "Vitamin C"]', 1, 'Leaves RBCs vulnerable to complement-mediated destruction. (Step-Up)'),
    (v_topic_id, '38: PNH classically presents with "cola-colored" urine in the morning and a high risk of:', '["Bleeding", "Venous Thrombosis (e.g., Budd-Chiari syndrome)", "Infection", "Heart failure"]', 1, 'Leading cause of death in PNH. (Pocket Medicine)'),
    (v_topic_id, '39: The primary treatment for PNH is ____, which blocks the complement cascade.', '["Steroids", "Eculizumab", "Warfarin", "Iron"]', 1, 'Monoclonal antibody against C5. (Harrison''s Ch. 94)'),
    (v_topic_id, '40: "Direct Antiglobulin Test (DAT/Coombs)" is POSITIVE in which condition?', '["G6PD deficiency", "Autoimmune Hemolytic Anemia (AIHA)", "Hereditary Spherocytosis", "Thalassemia"]', 1, 'Detects antibodies or complement already bound to RBCs. (Step-Up)'),
    (v_topic_id, '41: Sickle Cell Disease is caused by a point mutation (Valine for Glutamic acid) in the ____ chain.', '["Alpha", "Beta", "Gamma", "Delta"]', 1, 'HbS polymerizes when deoxygenated. (Harrison''s Ch. 94)'),
    (v_topic_id, '42: "Autosplenectomy" (shrunken, fibrotic spleen) in Sickle Cell patients is caused by:', '["Infection", "Repeated splenic infarctions", "Cancer", "None"]', 1, 'Usually complete by age 5. (Step-Up)'),
    (v_topic_id, '43: Sickle Cell patients are at increased risk of sepsis from which type of bacteria?', '["Gram-negative rods", "Encapsulated bacteria (S. pneumoniae, H. influenzae, N. meningitidis)", "Anaerobes", "Fungi"]', 1, 'Due to functional asplenia. (Pocket Medicine)'),
    (v_topic_id, '44: "Acute Chest Syndrome" in Sickle Cell is a leading cause of death and presents with:', '["Abdominal pain", "Fever, chest pain, and new lung infiltrate", "Headache", "Swollen joints"]', 1, 'Emergency; may require exchange transfusion. (Harrison''s Ch. 94)'),
    (v_topic_id, '45: "Dactylitis" (hand-foot syndrome) is often the first sign of SCD in infants, presenting with:', '["Rash", "Symmetric swelling and pain of hands and feet", "Blindness", "Cough"]', 1, 'Due to microvascular occlusion. (Step-Up)'),
    (v_topic_id, '46: Which medication increases "Hemoglobin F" levels and reduces the frequency of sickle crises?', '["Aspirin", "Hydroxyurea", "Penicillin", "Iron"]', 1, 'HbF interferes with HbS polymerization. (Pocket Medicine)'),
    (v_topic_id, '47: Sickle Cell patients with a sudden drop in hemoglobin and LOW reticulocyte count likely have:', '["Vaso-occlusive crisis", "Aplastic Crisis (usually from Parvovirus B19)", "Splenic sequestration", "Hemolysis"]', 1, 'The virus stops RBC production. (Harrison''s Ch. 94)'),
    (v_topic_id, '48: "Osteomyelitis" in a Sickle Cell patient is classically associated with which organism?', '["Staph aureus", "Salmonella", "Pseudomonas", "E. coli"]', 1, 'S. aureus is still common, but Salmonella is a high-yield association. (Step-Up)'),
    (v_topic_id, '49: "Papillary Necrosis" in the kidney causing hematuria is a common complication of:', '["Iron deficiency", "Sickle Cell Trait or Disease", "B12 deficiency", "None"]', 1, 'Vaso-occlusion in the renal medulla. (Pocket Medicine)'),
    (v_topic_id, '50: "Target cells" and "Howell-Jolly bodies" on a smear of a 10-year-old SCD patient suggest:', '["Recovery", "Functional asplenia", "Active infection", "Iron overdose"]', 1, 'The spleen is no longer filtering these cells. (Harrison''s Ch. 94)'),
    (v_topic_id, '51: "Primary Hemostasis" involves the formation of the:', '["Fibrin clot", "Platelet plug", "Thrombus", "Scab"]', 1, 'Defects lead to mucosal bleeding (epistaxis, petechiae). (Step-Up)'),
    (v_topic_id, '52: What is the most common inherited bleeding disorder?', '["Hemophilia A", "von Willebrand Disease (vWD)", "Hemophilia B", "Factor V Leiden"]', 1, 'Deficiency or dysfunction of vWF. (Pocket Medicine)'),
    (v_topic_id, '53: "von Willebrand Factor" (vWF) is required for platelet ____ to the subendothelium.', '["Aggregation", "Adhesion", "Activation", "Production"]', 1, 'Acts as a "bridge" via GpIb receptors. (Harrison''s Ch. 122)'),
    (v_topic_id, '54: "Immune Thrombocytopenic Purpura" (ITP) is characterized by isolated low platelets due to:', '["Marrow failure", "Autoantibodies against platelets", "Splenomegaly", "Infection"]', 1, 'Usually a diagnosis of exclusion. (Step-Up)'),
    (v_topic_id, '55: "Thrombotic Thrombocytopenic Purpura" (TTP) is caused by a deficiency of which enzyme?', '["G6PD", "ADAMTS13", "Protein C", "Antithrombin"]', 1, 'Leads to large vWF multimers and microthrombi. (Pocket Medicine)'),
    (v_topic_id, '56: The classic TTP pentad includes Fever, Microangiopathic Hemolytic Anemia (MAHA), Thrombocytopenia, Renal failure, and:', '["Joint pain", "Neurological symptoms (e.g., confusion, stroke)", "Rash", "Cough"]', 1, 'MAHA + Thrombocytopenia is enough to trigger urgent treatment. (Harrison''s Ch. 122)'),
    (v_topic_id, '57: What is the emergency treatment for TTP?', '["Platelet transfusion", "Plasmapheresis (Plasma exchange)", "Antibiotics", "Heparin"]', 1, 'NEVER give platelets as it can "fuel the fire." (Step-Up)'),
    (v_topic_id, '58: "Schistocytes" (helmet cells) on a blood smear are a hallmark of:', '["Iron deficiency", "Microangiopathic Hemolytic Anemia (e.g., TTP, HUS, DIC)", "Sickle cell", "Spherocytosis"]', 1, 'RBCs are sheared as they pass through fibrin mesh. (Pocket Medicine)'),
    (v_topic_id, '59: "Hemolytic Uremic Syndrome" (HUS) is classically associated with which infection in children?', '["Staph aureus", "E. coli O157:H7 (Shiga toxin)", "Salmonella", "Streptococcus"]', 1, 'Presents after a prodrome of bloody diarrhea. (Harrison''s Ch. 122)'),
    (v_topic_id, '60: "Bernard-Soulier Syndrome" is a defect in platelet ____ (GpIb receptor).', '["Aggregation", "Adhesion", "Secretion", "None"]', 1, 'Shows large platelets on smear. (Step-Up)'),
    (v_topic_id, '61: "Secondary Hemostasis" involves the coagulation cascade to form a stable ____ clot.', '["Platelet", "Fibrin", "Albumin", "Heme"]', 1, 'Defects lead to deep tissue bleeding (hemarthrosis). (Pocket Medicine)'),
    (v_topic_id, '62: "Prothrombin Time" (PT/INR) evaluates the ____ pathway.', '["Intrinsic", "Extrinsic", "Common", "Platelet"]', 1, 'Mainly Factor VII. (Harrison''s Ch. 122)'),
    (v_topic_id, '63: "Activated Partial Thromboplastin Time" (aPTT) evaluates the ____ pathway.', '["Extrinsic", "Intrinsic", "Platelet", "Fibrin"]', 1, 'Factors XII, XI, IX, VIII. (Step-Up)'),
    (v_topic_id, '64: "Hemophilia A" is a deficiency of Factor ____.', '["VII", "VIII", "IX", "XI"]', 1, 'X-linked recessive inheritance. (Pocket Medicine)'),
    (v_topic_id, '65: "Hemophilia B" (Christmas Disease) is a deficiency of Factor ____.', '["VIII", "IX", "X", "V"]', 1, 'Clinically indistinguishable from Hemophilia A. (Harrison''s Ch. 122)'),
    (v_topic_id, '66: Which vitamin is required for the synthesis of Factors II, VII, IX, X, Protein C, and Protein S?', '["Vitamin A", "Vitamin K", "Vitamin C", "Vitamin D"]', 1, 'Warfarin inhibits this vitamin''s recycling. (Step-Up)'),
    (v_topic_id, '67: "Disseminated Intravascular Coagulation" (DIC) is characterized by both widespread ____ and ____.', '["Fever; Chills", "Clotting; Bleeding", "Anemia; Leukemia", "None"]', 1, 'Consumptive coagulopathy. (Pocket Medicine)'),
    (v_topic_id, '68: In DIC, PT, aPTT, and D-dimer are ____, while Fibrinogen is ____.', '["Low; High", "High; Low", "Normal; Normal", "None"]', 1, 'Fibrinogen is consumed in the clotting process. (Harrison''s Ch. 122)'),
    (v_topic_id, '69: "Vitamin K deficiency" is common in newborns, which is why they receive an IM injection at birth to prevent:', '["Infection", "Vitamin K Deficiency Bleeding (VKDB)", "Jaundice", "Diarrhea"]', 1, 'Liver stores are low and gut flora is absent. (Step-Up)'),
    (v_topic_id, '70: "Mixing Study" that fails to correct the aPTT suggests the presence of a/an:', '["Factor deficiency", "Inhibitor (e.g., Lupus anticoagulant, Factor antibody)", "Infection", "None"]', 1, 'If it corrects, it was a deficiency. (Pocket Medicine)'),
    (v_topic_id, '71: What is the most common inherited cause of hypercoagulability (thrombophilia)?', '["Protein C deficiency", "Factor V Leiden", "Antithrombin deficiency", "Prothrombin mutation"]', 1, 'Factor V is resistant to inactivation by Protein C. (Harrison''s Ch. 123)'),
    (v_topic_id, '72: "Protein C" and "Protein S" are natural ____.', '["Clotting factors", "Anticoagulants", "Antibodies", "Platelets"]', 1, 'They inactivate Factors Va and VIIIa. (Step-Up)'),
    (v_topic_id, '73: "Antiphospholipid Syndrome" (APS) presents with recurrent thrombosis and:', '["Fever", "Pregnancy loss", "Weight gain", "Bleeding"]', 1, 'Associated with Lupus anticoagulant and Anticardiolipin antibodies. (Pocket Medicine)'),
    (v_topic_id, '74: "Heparin-Induced Thrombocytopenia" (HIT) is caused by antibodies against:', '["Platelets only", "Heparin-Platelet Factor 4 (PF4) complex", "Factor X", "Thrombin"]', 1, 'Paradoxically increases the risk of thrombosis. (Harrison''s Ch. 123)'),
    (v_topic_id, '75: What is the FIRST step when HIT is suspected?', '["Give more heparin", "Stop all heparin and start a non-heparin anticoagulant (e.g., Argatroban)", "Give platelets", "Warfarin only"]', 1, 'Crucial to prevent catastrophic thrombosis. (Step-Up)'),
    (v_topic_id, '76: "Warfarin-induced skin necrosis" can occur in patients with an underlying deficiency of:', '["Iron", "Protein C or S", "Factor VIII", "Vitamin C"]', 1, 'Warfarin initially creates a pro-thrombotic state as Protein C drops first. (Pocket Medicine)'),
    (v_topic_id, '77: Which hypercoagulable state is most strongly associated with venous AND arterial clots?', '["Factor V Leiden", "Antiphospholipid Syndrome", "Protein C deficiency", "Prothrombin G20210A"]', 1, 'Most others are primarily venous. (Harrison''s Ch. 123)'),
    (v_topic_id, '78: "Antithrombin III" deficiency makes the patient resistant to the action of:', '["Warfarin", "Heparin", "Aspirin", "Clopidogrel"]', 1, 'Heparin requires Antithrombin to work. (Step-Up)'),
    (v_topic_id, '79: A 25-year-old with a DVT and a positive family history should be screened for:', '["Infection", "Thrombophilia (Hypercoagulable states)", "Diabetes", "Asthma"]', 1, 'Workup usually performed after the acute event resolves. (Pocket Medicine)'),
    (v_topic_id, '80: "Virchow''s Triad" for thrombosis includes Stasis, Hypercoagulability, and:', '["Fever", "Endothelial Injury", "Obesity", "Smoking"]', 1, 'Classic framework for understanding DVT/PE risk. (Harrison''s Ch. 123)'),
    (v_topic_id, '81: "TRALI" (Transfusion-Related Acute Lung Injury) is characterized by sudden pulmonary edema and ____ within 6 hours.', '["High fever", "Hypotension", "Hypertension", "None"]', 1, 'Due to donor antibodies reacting with recipient neutrophils. (Harrison''s Ch. 119)'),
    (v_topic_id, '82: "TACO" (Transfusion-Associated Circulatory Overload) presents with pulmonary edema and ____.', '["Low BP", "Hypertension and high JVP", "Fever", "Rash"]', 1, 'Simply a volume overload problem; treated with diuretics. (Step-Up)'),
    (v_topic_id, '83: "Acute Hemolytic Transfusion Reaction" is most commonly due to ____ incompatibility.', '["Rh", "ABO (clerical error)", "HLA", "IgA"]', 1, 'Presents with fever, flank pain, and DIC. (Pocket Medicine)'),
    (v_topic_id, '84: "Febrile Non-hemolytic Transfusion Reaction" (FNHTR) is a benign rise in temp caused by:', '["Bacteria", "Cytokines released from donor WBCs during storage", "Virus", "None"]', 1, 'The most common transfusion reaction. (Harrison''s Ch. 119)'),
    (v_topic_id, '85: An IgA-deficient patient is at risk for ____ during blood transfusion.', '["Fever", "Anaphylaxis", "Heart failure", "None"]', 1, 'Requires washed RBCs. (Step-Up)'),
    (v_topic_id, '86: "Delayed Hemolytic Transfusion Reaction" occurs 1-2 weeks later due to a/an ____ response.', '["Infection", "Anamnestic antibody response (often Rh or Kidd)", "Allergy", "None"]', 1, 'Presents with a drop in hemoglobin and mild jaundice. (Pocket Medicine)'),
    (v_topic_id, '87: "Cryoprecipitate" is used primarily to replace:', '["Albumin", "Fibrinogen and Factor VIII/vWF", "Platelets", "RBCs"]', 1, 'Often used in DIC or massive hemorrhage. (Harrison''s Ch. 119)'),
    (v_topic_id, '88: "Fresh Frozen Plasma" (FFP) contains:', '["Only Factor VIII", "All clotting factors and proteins", "Platelets", "None"]', 1, 'Used to reverse Warfarin or in multiple factor deficiencies. (Step-Up)'),

    -- SECTION 10-16: LEUKEMIAS, MPN, PLASMA CELLS
    (v_topic_id, '89: Acute Myeloid Leukemia (AML) is characterized by a rapid proliferation of ____ in the bone marrow.', '["Mature neutrophils", "Myeloblasts (>20%)", "Lymphocytes", "Platelets"]', 1, 'Crowds out normal hematopoiesis. (Harrison''s Ch. 110)'),
    (v_topic_id, '90: "Auer rods" on a bone marrow aspirate are pathognomonic for:', '["ALL", "AML (especially M3 sub-type)", "CLL", "CML"]', 1, 'Needle-like cytoplasmic inclusions. (Step-Up)'),
    (v_topic_id, '91: "Acute Promyelocytic Leukemia" (APL / M3) is associated with which translocation?', '["t(9;22)", "t(15;17)", "t(8;14)", "t(12;21)"]', 1, 'Involves the RAR-alpha gene. (Pocket Medicine)'),
    (v_topic_id, '92: APL is a medical emergency due to the high risk of:', '["Infection", "Disseminated Intravascular Coagulation (DIC)", "Brain tumor", "Liver failure"]', 1, 'Release of pro-coagulants from granules. (Harrison''s Ch. 110)'),
    (v_topic_id, '93: The treatment of choice for APL includes ____, which forces the blasts to differentiate.', '["Cytarabine", "All-Trans Retinoic Acid (ATRA)", "Methotrexate", "Imatinib"]', 1, 'Can also use arsenic trioxide. (Step-Up)'),
    (v_topic_id, '94: "Acute Lymphoblastic Leukemia" (ALL) is the most common malignancy in:', '["Elderly", "Children", "Teens", "Men"]', 1, 'Presents with bone pain, fever, and bruising. (Pocket Medicine)'),
    (v_topic_id, '95: "Terminal Deoxynucleotidyl Transferase" (TdT) is a positive marker for:', '["AML", "ALL", "CLL", "CML"]', 1, 'A DNA polymerase found in lymphoblasts. (Harrison''s Ch. 110)'),
    (v_topic_id, '96: ALL has a high propensity to spread to which "sanctuary" sites?', '["Liver and Spleen", "CNS and Testes", "Bones", "Lungs"]', 1, 'Requires intrathecal chemotherapy. (Step-Up)'),
    (v_topic_id, '97: Which translocation in childhood ALL is associated with a GOOD prognosis?', '["t(9;22)", "t(12;21)", "t(4;11)", "None"]', 1, 'Common in B-cell ALL. (Pocket Medicine)'),
    (v_topic_id, '98: "Tumor Lysis Syndrome" (TLS) after starting chemo for leukemia involves high levels of:', '["Sugar", "Uric acid, Potassium, and Phosphate", "Calcium", "Sodium"]', 1, 'Massive release of intracellular contents. (Harrison''s Ch. 110)'),
    (v_topic_id, '99: "Chronic Myeloid Leukemia" (CML) is defined by the ____ chromosome, t(9;22).', '["Philadelphia", "New York", "London", "Tokyo"]', 0, 'Creates the BCR-ABL fusion protein (a tyrosine kinase). (Harrison''s Ch. 110)'),
    (v_topic_id, '100: What is the first-line treatment for CML?', '["Chemotherapy", "Tyrosine Kinase Inhibitors (e.g., Imatinib)", "Radiation", "Surgery"]', 1, 'Revolutionized the prognosis of CML. (Step-Up)'),
    (v_topic_id, '101: "Leukocyte Alkaline Phosphatase" (LAP) score is ____ in CML and ____ in a leukemoid reaction.', '["High; Low", "Low; High", "Normal; Normal", "None"]', 1, 'LAP is low in CML because the cells are malignant/dysfunctional. (Pocket Medicine)'),
    (v_topic_id, '102: CML can progress to which life-threatening phase?', '["Chronic phase", "Blast Crisis (AML or ALL)", "Remission", "None"]', 1, 'Requires immediate aggressive therapy. (Harrison''s Ch. 110)'),
    (v_topic_id, '103: "Chronic Lymphocytic Leukemia" (CLL) is characterized by the accumulation of mature-appearing ____.', '["Neutrophils", "B-cells", "T-cells", "Plasma cells"]', 1, 'The most common leukemia in adults in the West. (Step-Up)'),
    (v_topic_id, '104: "Smudge cells" on a peripheral smear are characteristic of:', '["AML", "CLL", "CML", "ALL"]', 1, 'Fragile lymphocytes burst during the smear preparation. (Pocket Medicine)'),
    (v_topic_id, '105: "Richter Transformation" refers to CLL progressing into:', '["AML", "Diffuse Large B-cell Lymphoma (DLBCL)", "Hodgkin Lymphoma", "None"]', 1, 'Presents with sudden lymph node enlargement and fever. (Harrison''s Ch. 110)'),
    (v_topic_id, '106: "Hairy Cell Leukemia" is a mature B-cell neoplasm that presents with massive splenomegaly and ____.', '["High WBC", "Pancytopenia (dry tap on marrow)", "High platelets", "Cough"]', 1, 'Cells have "hairy" projections and are TRAP-positive. (Step-Up)'),
    (v_topic_id, '107: What is the treatment of choice for Hairy Cell Leukemia?', '["Imatinib", "Cladribine (2-CdA)", "Steroids", "Rituximab only"]', 1, 'Very high response rates. (Pocket Medicine)'),
    (v_topic_id, '108: Most patients with CLL are diagnosed ____ on routine blood work.', '["After severe bleeding", "Incidentally (asymptomatic lymphocytosis)", "After bone fractures", "None"]', 1, 'Often managed with "watchful waiting" if asymptomatic. (Harrison''s Ch. 110)'),
    (v_topic_id, '109: "Polycythemia Vera" (PV) is caused by a mutation in ____ in >95% of cases.', '["BCR-ABL", "JAK2 (V617F)", "BRAF", "c-MYC"]', 1, 'Leads to uncontrolled RBC production. (Harrison''s Ch. 110)'),
    (v_topic_id, '110: "Aquagenic pruritus" (itching after a hot shower) is a classic symptom of:', '["Liver disease", "Polycythemia Vera", "Diabetes", "Cancer"]', 1, 'Due to mast cell degranulation. (Step-Up)'),
    (v_topic_id, '111: "Essential Thrombocythemia" (ET) is characterized by isolated ____.', '["Anemia", "Thrombocytosis (high platelets)", "Leukopenia", "High RBCs"]', 1, 'Also often associated with JAK2 mutations. (Pocket Medicine)'),
    (v_topic_id, '112: "Primary Myelofibrosis" is characterized by marrow fibrosis and ____ cells on peripheral smear.', '["Bite", "Tear-drop RBCs (Dacrocytes)", "Target", "Smudge"]', 1, '"Cells crying because the marrow is scarred." (Harrison''s Ch. 110)'),
    (v_topic_id, '113: Erythropoietin (EPO) levels in Polycythemia Vera are typically:', '["High", "Low", "Normal", "Variable"]', 1, 'The production is autonomous, suppressing EPO. (Step-Up)'),
    (v_topic_id, '114: "Secondary Polycythemia" (high RBCs but high EPO) can be caused by:', '["Smoking/Hypoxia", "Renal Cell Carcinoma (EPO-secreting)", "Sleep Apnea", "All of the above"]', 3, 'The kidney thinks it needs more oxygen capacity. (Pocket Medicine)'),
    (v_topic_id, '115: What is the first-line treatment for Polycythemia Vera?', '["Chemotherapy", "Phlebotomy and Aspirin", "Radiation", "Surgery"]', 1, 'Hydroxyurea is added for high-risk patients. (Harrison''s Ch. 110)'),
    (v_topic_id, '116: ET and Myelofibrosis also carry an increased risk of transformation to:', '["CML", "Acute Myeloid Leukemia (AML)", "Lymphoma", "None"]', 1, 'Known as "spent phase." (Step-Up)'),
    (v_topic_id, '117: "Hyperviscosity Syndrome" (headache, blurred vision) in MPNs is due to:', '["High sugar", "High cell counts (high Hct or Platelets)", "Infection", "None"]', 1, 'Blood is too "thick" to flow smoothly. (Pocket Medicine)'),
    (v_topic_id, '118: "Erythromelalgia" (burning pain and redness in hands/feet) is a feature of ET and PV, treated with:', '["Steroids", "Aspirin", "Antibiotics", "Water"]', 1, 'Due to microvascular occlusion. (Harrison''s Ch. 110)'),
    (v_topic_id, '119: "Multiple Myeloma" (MM) is a malignancy of which cell type?', '["B-cells", "Plasma cells", "T-cells", "Stem cells"]', 1, 'Produces a monoclonal (M) protein. (Harrison''s Ch. 111)'),
    (v_topic_id, '120: The "CRAB" criteria for Multiple Myeloma stand for Calcium (high), Renal failure, Anemia, and:', '["Brain tumor", "Bone lesions (lytic)", "Bleeding", "Bronchospasm"]', 1, 'Lytic lesions caused by osteoclast activation. (Step-Up)'),
    (v_topic_id, '121: "Rouleaux formation" (RBCs stacked like coins) on a smear suggests:', '["Iron deficiency", "Multiple Myeloma", "Sickle cell", "Dehydration"]', 1, 'Due to high serum protein/paraproteins. (Pocket Medicine)'),
    (v_topic_id, '122: "Bence-Jones proteins" found in the urine are actually:', '["Albumin", "Monoclonal Free Light Chains", "Sugar", "Hemoglobin"]', 1, 'They are too small to be detected by standard dipstick (which checks for albumin). (Harrison''s Ch. 111)'),
    (v_topic_id, '123: "Monoclonal Gammopathy of Undetermined Significance" (MGUS) is defined by M-protein < 3g and marrow plasma cells < ____ %.', '["5", "10", "20", "50"]', 1, 'Requires monitoring as it can progress to MM. (Step-Up)'),
    (v_topic_id, '124: "Waldenstrom Macroglobulinemia" is a plasma cell disorder that exclusively produces which antibody?', '["IgG", "IgM", "IgA", "IgE"]', 1, 'Large IgM pentamers cause severe hyperviscosity. (Pocket Medicine)'),
    (v_topic_id, '125: Multiple Myeloma bone lesions are "lytic" and therefore do NOT show up on which imaging test?', '["X-ray", "Bone Scan (Nuclear medicine)", "CT", "MRI"]', 1, 'Bone scans detect osteoblastic activity; use Skeletal Survey (X-ray) instead. (Harrison''s Ch. 111)'),
    (v_topic_id, '126: "Amyloidosis (AL)" in MM is due to the deposition of:', '["Sugar", "Misfolded Light Chains", "Fibrin", "Collagen"]', 1, 'Can cause macroglossia, heart failure, and nephrotic syndrome. (Step-Up)'),
    (v_topic_id, '127: Renal failure in Multiple Myeloma is often due to "Myeloma Kidney," which is:', '["Infection", "Light Chain Cast Nephropathy", "Stones", "Diabetes"]', 1, 'Light chains are toxic to renal tubules. (Pocket Medicine)'),
    (v_topic_id, '128: What is the definitive treatment for fit patients with Multiple Myeloma?', '["Chemotherapy only", "Autologous Stem Cell Transplant", "Surgery", "Wait and watch"]', 1, 'Preceded by induction therapy (e.g., VRd). (Harrison''s Ch. 111)'),
    (v_topic_id, '129: Myelodysplastic Syndrome (MDS) is a group of clonal disorders characterized by ____ hematopoiesis.', '["Overactive", "Ineffective/Dysplastic", "Normal", "Fast"]', 1, 'Common in elderly; "pre-leukemia." (Step-Up)'),
    (v_topic_id, '130: "Pseudo-Pelger-Huet anomaly" (bilobed neutrophils) is a classic finding in:', '["CLL", "MDS", "AML", "B12 deficiency"]', 1, 'Sign of myeloid dysplasia. (Pocket Medicine)'),
    (v_topic_id, '131: "5q- Syndrome" is a sub-type of MDS that typically responds well to:', '["Insulin", "Lenalidomide", "Chemotherapy", "Iron"]', 1, 'Unique genetic association. (Harrison''s Ch. 110)'),
    (v_topic_id, '132: The most serious risk of MDS is progression to:', '["Lymphoma", "Acute Myeloid Leukemia (AML)", "Myelofibrosis", "None"]', 1, 'Requires monitoring of blast percentage. (Step-Up)'),
    (v_topic_id, '133: "Ringed sideroblasts" in MDS suggest which sub-type?', '["MDS with excess blasts", "MDS with ring sideroblasts (MDS-RS)", "Del(5q)", "None"]', 1, 'Often associated with SF3B1 mutations. (Pocket Medicine)'),
    (v_topic_id, '134: MDS typically presents as macrocytic anemia and ____ in an elderly patient.', '["Weight gain", "Pancytopenia", "High WBC", "High sugar"]', 1, 'The marrow is cellular but the cells don''t make it out. (Harrison''s Ch. 110)'),
    (v_topic_id, '135: "Azacitidine" and "Decitabine" are used in MDS and work as:', '["Antibiotics", "Hypomethylating agents", "Hormones", "None"]', 1, 'Standard therapy for higher-risk MDS. (Step-Up)'),
    (v_topic_id, '136: A "dry tap" on bone marrow biopsy is common in Myelofibrosis and ____.', '["ALL", "Hairy Cell Leukemia", "CLL", "None"]', 1, 'Marrow is either too fibrotic or too packed. (Pocket Medicine)'),
    (v_topic_id, '137: "Neutrophilia" (High neutrophils) with a "Left Shift" (bands) is classic for:', '["Viral infection", "Bacterial infection", "Parasites", "Allergy"]', 1, 'The marrow is releasing immature cells to fight. (Step-Up)'),
    (v_topic_id, '138: "Eosinophilia" is a hallmark of "NAACP": Neoplasm, Allergy, Addison''s, Collagen vascular, and:', '["Parasites", "Pregnancy", "Pneumonia", "Pain"]', 0, 'High-yield mnemonic for eosinophilia. (Harrison''s Ch. 110)'),
    (v_topic_id, '139: "Atypical Lymphocytes" (Downey cells) are classic for:', '["Bacterial sepsis", "Infectious Mononucleosis (EBV)", "CLL", "Iron deficiency"]', 1, 'Reactive T-cells fighting the B-cell infection. (Pocket Medicine)'),
    (v_topic_id, '140: "Basophilia" is rare and should raise suspicion for a myeloproliferative disorder like:', '["ALL", "CML", "Anemia", "ITP"]', 1, 'Classic finding in the chronic phase of CML. (Step-Up)'),
    (v_topic_id, '141: "Dohle bodies" in neutrophils are signs of:', '["Cancer", "Severe infection or inflammation", "B12 deficiency", "Normal aging"]', 1, 'Blue, oval inclusions in the cytoplasm. (Pocket Medicine)'),
    (v_topic_id, '142: "Hypersegmented Neutrophils" = ?', '["Iron deficiency", "Megaloblastic Anemia (B12/Folate)", "Leukemia", "None"]', 1, 'Pathognomonic for impaired DNA synthesis. (Harrison''s Ch. 95)'),
    (v_topic_id, '143: "Leukopenia" + "Anemia" + "Thrombocytopenia" = ?', '["Hemolysis", "Pancytopenia (e.g., Aplastic anemia, Marrow infiltration)", "Infection", "None"]', 1, 'Requires bone marrow evaluation. (Step-Up)'),
    (v_topic_id, '144: "Bence-Jones" protein in urine = ?', '["Diabetes", "Multiple Myeloma", "Stones", "Normal"]', 1, 'Monoclonal light chains. (Pocket Medicine)'),
    (v_topic_id, '145: "Philadelphia chromosome" t(9;22) = ?', '["AML", "CML", "CLL", "ALL"]', 1, 'Also found in some ALL cases (bad prognosis). (Harrison''s Ch. 110)'),
    (v_topic_id, '146: "JAK2" mutation = ?', '["CML", "Myeloproliferative Neoplasms (PV, ET, MF)", "Lymphoma", "None"]', 1, 'Constitutive activation of tyrosine kinase. (Step-Up)'),
    (v_topic_id, '147: "Smudge cells" = ?', '["ALL", "CLL", "CML", "AML"]', 1, 'Fragile CLL lymphocytes. (Pocket Medicine)'),
    (v_topic_id, '148: "Auer rods" = ?', '["ALL", "AML", "CML", "CLL"]', 1, 'Myeloblast granules. (Harrison''s Ch. 110)'),
    (v_topic_id, '149: "t(15;17)" = ?', '["ALL", "APL (AML M3)", "Burkitt", "Follicular"]', 1, 'APL with high risk of DIC. (Step-Up)'),
    (v_topic_id, '150: "Starry sky" pattern on biopsy = ?', '["Follicular", "Burkitt Lymphoma", "Hodgkin", "None"]', 1, 'Macrophages eating apoptotic cells. (Pocket Medicine)'),
    (v_topic_id, '151: "Aplastic Anemia" is defined by pancytopenia and ____ marrow.', '["Hypercellular", "Hypocellular (Fatty replacement)", "Fibrotic", "Bloody"]', 1, 'Often idiopathic or drug-induced. (Harrison''s Ch. 98)'),
    (v_topic_id, '152: Which medication is a common cause of drug-induced aplastic anemia?', '["Aspirin", "Chloramphenicol", "Penicillin", "Insulin"]', 1, 'Classic board association. (Step-Up)'),
    (v_topic_id, '153: "Fanconi Anemia" is an inherited form of aplastic anemia associated with:', '["Short stature and thumb abnormalities", "Vision loss", "Heart failure", "None"]', 0, 'Risk of progression to AML. (Pocket Medicine)'),
    (v_topic_id, '154: "Pure Red Cell Aplasia" (PRCA) is an isolated drop in RBCs often associated with:', '["Lung cancer", "Thymoma", "Liver failure", "Kidney failure"]', 1, 'RBC production stops; can also be caused by Parvovirus B19. (Harrison''s Ch. 98)'),
    (v_topic_id, '155: "Hemochromatosis" is iron overload. Primary type is due to mutations in:', '["HFE gene", "CFTR", "ATP7B", "None"]', 0, 'Autosomal recessive; leads to "Bronze Diabetes." (Step-Up)'),
    (v_topic_id, '156: "Phlebotomy" is the treatment of choice for:', '["Anemia", "Hemochromatosis and Polycythemia Vera", "Leukemia", "None"]', 1, 'Removes excess iron/RBCs. (Pocket Medicine)'),
    (v_topic_id, '157: "Wilson Disease" is a disorder of ____ metabolism, not iron.', '["Zinc", "Copper", "Magnesium", "Calcium"]', 1, 'Associated with Kayser-Fleischer rings. (Harrison''s Ch. 339)'),
    (v_topic_id, '158: "Gaucher Disease" is a lysosomal storage disorder that presents with splenomegaly and ____ cells.', '["Target", "Crumpled tissue paper (Gaucher cells)", "Heinz", "None"]', 1, 'Due to glucocerebrosidase deficiency. (Step-Up)'),
    (v_topic_id, '159: "Porphyria Cutanea Tarda" (PCT) is the most common porphyria and presents with:', '["Abdominal pain only", "Skin blisters on sun-exposed areas", "Blindness", "None"]', 1, 'Associated with Hepatitis C and iron overload. (Pocket Medicine)'),
    (v_topic_id, '160: "Acute Intermittent Porphyria" (AIP) presents with the "5 Ps": Painful abdomen, Polyneuropathy, Psychosis, Pink urine, and:', '["Pneumonia", "Precipitated by drugs (e.g., P450 inducers)", "Palpitations", "None"]', 1, 'Due to deficiency of porphobilinogen deaminase. (Harrison''s Ch. 415)'),
    (v_topic_id, '161: "Splenomegaly" is a hallmark of Myelofibrosis and which leukemia?', '["CML", "ALL", "CLL", "AML"]', 0, 'The spleen takes over hematopoiesis (extramedullary). (Step-Up)'),
    (v_topic_id, '162: "Pruritus after showering" = ?', '["Lupus", "Polycythemia Vera", "Diabetes", "Liver failure"]', 1, 'Classic PV symptom. (Pocket Medicine)'),
    (v_topic_id, '163: "Lytic bone lesions" + "Hypercalcemia" = ?', '["Bone cancer", "Multiple Myeloma", "Hypoparathyroidism", "None"]', 1, 'Standard MM presentation. (Harrison''s Ch. 111)'),
    (v_topic_id, '164: "Low LAP score" = ?', '["Leukemoid reaction", "Chronic Myeloid Leukemia (CML)", "Infection", "None"]', 1, 'Distinguishes CML from reactive high WBC. (Step-Up)'),
    (v_topic_id, '165: "High LAP score" = ?', '["CML", "Leukemoid Reaction (infection/stress)", "AML", "None"]', 1, 'Mature neutrophils are functional. (Pocket Medicine)'),
    (v_topic_id, '166: "Target cells" are seen in Thalassemia, Liver disease, and ____.', '["Sickle Cell and Asplenia", "Iron deficiency", "B12 deficiency", "None"]', 0, 'Excess membrane relative to volume. (Harrison''s Ch. 94)'),
    (v_topic_id, '167: "Spherocytes" + "Positive Coombs" = ?', '["Hereditary Spherocytosis", "Autoimmune Hemolytic Anemia (AIHA)", "G6PD", "None"]', 1, 'Antibodies are coating the cells. (Step-Up)'),
    (v_topic_id, '168: "Spherocytes" + "Negative Coombs" = ?', '["AIHA", "Hereditary Spherocytosis", "Thalassemia", "None"]', 1, 'Intrinsic membrane defect. (Pocket Medicine)'),
    (v_topic_id, '169: "Schistocytes" = ?', '["MAHA (TTP/HUS/DIC)", "Sickle cell", "Target cells", "None"]', 0, 'Fragmented RBCs. (Harrison''s Ch. 122)'),
    (v_topic_id, '170: "Bite cells" = ?', '["Spherocytosis", "G6PD Deficiency", "Leukemia", "None"]', 1, 'Due to splenic "pitting" of Heinz bodies. (Step-Up)'),
    (v_topic_id, '171: "Basophilic stippling" = ?', '["Lead Poisoning and Thalassemias", "Iron deficiency", "B12", "None"]', 0, 'Aggregated ribosomes. (Pocket Medicine)'),
    (v_topic_id, '172: "Howell-Jolly bodies" = ?', '["Splenectomy or Functional Asplenia", "Iron deficiency", "Lead poisoning", "None"]', 0, 'Nuclear remnants. (Harrison''s Ch. 110)'),
    (v_topic_id, '173: "Teardrop cells" = ?', '["Multiple Myeloma", "Myelofibrosis", "Iron deficiency", "None"]', 1, 'RBCs squeezed out of fibrotic marrow. (Step-Up)'),
    (v_topic_id, '174: "Pappenheimer bodies" = ?', '["Lead poisoning", "Sideroblastic Anemia", "B12", "None"]', 1, 'Iron-containing granules. (Pocket Medicine)'),
    (v_topic_id, '175: "Rouleaux" = ?', '["Sickle cell", "Multiple Myeloma", "Spherocytosis", "None"]', 1, 'Coin-stack appearance. (Harrison''s Ch. 111)'),
    (v_topic_id, '176: "Acanthocytes" (Spur cells) = ?', '["Diabetes", "Liver disease (Cirrhosis) or Abetalipoproteinemia", "Iron deficiency", "None"]', 1, 'Irregular thorny projections. (Step-Up)'),

    -- SECTION 17-23: LYMPHOMAS, SOLID TUMORS
    (v_topic_id, '177: Hodgkin Lymphoma is characterized by the presence of which pathognomonic cell?', '["Blast cells", "Reed-Sternberg cells (Owl''s eye nuclei)", "Smudge cells", "Auer rods"]', 1, 'Large, multi-nucleated B-cells. (Harrison''s Ch. 110)'),
    (v_topic_id, '178: Which markers are typically positive on Reed-Sternberg cells in classic HL?', '["CD19 and CD20", "CD15 and CD30", "CD3 and CD4", "CD10"]', 1, 'Helps distinguish it from Non-Hodgkin Lymphoma. (Step-Up)'),
    (v_topic_id, '179: "Pel-Ebstein fever" in HL refers to fever that:', '["Never goes away", "Cycles (high for days, low for days)", "Occurs only at night", "None"]', 1, 'A rare but classic board association. (Pocket Medicine)'),
    (v_topic_id, '180: What is the most common subtype of Hodgkin Lymphoma?', '["Lymphocyte-rich", "Nodular Sclerosis", "Mixed cellularity", "Lymphocyte-depleted"]', 1, 'Common in young women; presents with a mediastinal mass. (Harrison''s Ch. 110)'),
    (v_topic_id, '181: HL typically spreads in a/an ____ fashion, while NHL is more ____.', '["Random; Linear", "Contiguous (node-to-node); Non-contiguous/disseminated", "Slow; Fast", "None"]', 1, 'HL is usually localized to a single group of nodes initially. (Step-Up)'),
    (v_topic_id, '182: "B symptoms" in lymphoma include weight loss, drenching night sweats, and:', '["Fever > 38C", "Rash", "Cough", "Diarrhea"]', 0, 'Indicate a worse prognosis and higher tumor burden. (Pocket Medicine)'),
    (v_topic_id, '183: Hodgkin Lymphoma has a strong association with which virus in some subtypes?', '["HIV", "Epstein-Barr Virus (EBV)", "HPV", "Hepatitis B"]', 1, 'Especially in the mixed cellularity and lymphocyte-depleted types. (Harrison''s Ch. 110)'),
    (v_topic_id, '184: A patient with HL who experiences "pain in lymph nodes after drinking alcohol" likely has:', '["Allergy", "Classic (though rare) sign of Hodgkin Lymphoma", "Liver failure", "None"]', 1, 'High-yield clinical pearl. (Step-Up)'),
    (v_topic_id, '185: What is the standard chemotherapy regimen for Hodgkin Lymphoma?', '["CHOP", "ABVD (Adriamycin, Bleomycin, Vinblastine, Dacarbazine)", "R-CHOP", "7+3"]', 1, 'Cure rates are high even in advanced stages. (Pocket Medicine)'),
    (v_topic_id, '186: Which HL subtype has the BEST prognosis?', '["Lymphocyte-depleted", "Lymphocyte-rich", "Mixed cellularity", "Nodular sclerosis"]', 1, 'Characterized by many mature lymphocytes and rare RS cells. (Harrison''s Ch. 110)'),
    (v_topic_id, '187: What is the most common subtype of Non-Hodgkin Lymphoma?', '["Follicular", "Diffuse Large B-Cell Lymphoma (DLBCL)", "Burkitt", "Mantle Cell"]', 1, 'Aggressive but potentially curable. (Step-Up)'),
    (v_topic_id, '188: "Follicular Lymphoma" is characterized by the t(14;18) translocation involving which gene?', '["c-MYC", "BCL-2", "BCR-ABL", "Cyclin D1"]', 1, 'BCL-2 overexpression inhibits apoptosis. (Pocket Medicine)'),
    (v_topic_id, '189: "Burkitt Lymphoma" is characterized by the t(8;14) translocation involving which gene?', '["BCL-2", "c-MYC", "BCL-6", "RAR-alpha"]', 1, 'Promotes rapid cell growth. (Harrison''s Ch. 110)'),
    (v_topic_id, '190: The endemic (African) form of Burkitt Lymphoma usually presents as a mass in the:', '["Abdomen", "Jaw/Face", "Neck", "Groin"]', 1, 'Strongly associated with EBV. (Step-Up)'),
    (v_topic_id, '191: "Mantle Cell Lymphoma" is characterized by the t(11;14) translocation involving:', '["c-MYC", "Cyclin D1", "BCL-2", "None"]', 1, 'Usually has a poor prognosis. (Pocket Medicine)'),
    (v_topic_id, '192: "Marginal Zone Lymphoma" (MALToma) of the stomach is strongly associated with:', '["H. pylori infection", "Smoking", "Alcohol", "NSAIDs"]', 0, 'Can often be treated with H. pylori eradication alone. (Harrison''s Ch. 110)'),
    (v_topic_id, '193: "Mycosis Fungoides" is a T-cell lymphoma that primarily affects the:', '["Liver", "Skin", "Bones", "Lungs"]', 1, 'Presents with patches, plaques, and "Sezary cells" in the blood. (Step-Up)'),
    (v_topic_id, '194: What is the standard chemotherapy regimen for most B-cell Non-Hodgkin Lymphomas?', '["ABVD", "R-CHOP (Rituximab, Cyclophosphamide, Doxorubicin, Vincristine, Prednisone)", "BEACOPP", "None"]', 1, 'Rituximab is a CD20 antibody. (Pocket Medicine)'),
    (v_topic_id, '195: "Indolent" lymphomas (like Follicular) are generally:', '["Curable with chemo", "Not curable but have long survival (years/decades)", "Fast growing", "Painful"]', 1, 'Often managed with "watchful waiting" until symptoms develop. (Harrison''s Ch. 110)'),
    (v_topic_id, '196: Which lymphoma presents with "painless lymphadenopathy" that waxes and wanes?', '["Burkitt", "Follicular Lymphoma", "DLBCL", "Anaplastic Large Cell"]', 1, 'Classic description of an indolent B-cell lymphoma. (Step-Up)'),
    (v_topic_id, '197: What is the single most important risk factor for lung cancer?', '["Asbestos", "Cigarette Smoking", "Radon", "Air pollution"]', 1, 'Responsible for ~80-90% of cases. (Harrison''s Ch. 110)'),
    (v_topic_id, '198: Which type of lung cancer is the most common in BOTH smokers and non-smokers?', '["Squamous cell", "Adenocarcinoma", "Small cell", "Large cell"]', 1, 'Usually peripheral in location. (Pocket Medicine)'),
    (v_topic_id, '199: "Squamous Cell Carcinoma" of the lung is classically associated with:', '["Peripheral location", "Central location and Hypercalcemia (PTHrP)", "Non-smokers", "None"]', 1, '"S"quamous, "S"moking, "S"entally located, "S"ecretes PTHrP. (Step-Up)'),
    (v_topic_id, '200: "Small Cell Lung Cancer" (SCLC) is highly aggressive and often presents with:', '["Paraneoplastic syndromes (SIADH, ACTH, Lambert-Eaton)", "Surgery as first-line", "Peripheral nodules", "None"]', 0, 'Rarely treatable by surgery; usually managed with chemo/rad. (Harrison''s Ch. 110)'),
    (v_topic_id, '201: "Pancoast Tumor" (Superior Sulcus Tumor) can cause Horner Syndrome by compressing which structure?', '["Vagus nerve", "Sympathetic Chain/Ganglion", "Phrenic nerve", "Trachea"]', 1, 'Presents with ptosis, miosis, and anhidrosis. (Pocket Medicine)'),
    (v_topic_id, '202: "Superior Vena Cava (SVC) Syndrome" (facial swelling, distended neck veins) is a medical emergency often caused by:', '["Pneumonia", "Lung Cancer (especially Small Cell)", "Asthma", "Heart failure"]', 1, 'Requires urgent diagnosis and treatment (often radiation). (Step-Up)'),
    (v_topic_id, '203: "Lambert-Eaton Myasthenic Syndrome" presents with proximal muscle weakness that ____ with repetitive use.', '["Worsens", "Improves", "Stays the same", "None"]', 1, 'Autoantibodies against presynaptic calcium channels. (Harrison''s Ch. 110)'),
    (v_topic_id, '204: Lung cancer screening with annual Low-Dose CT (LDCT) is recommended for high-risk smokers starting at age:', '["40", "50", "60", "65"]', 1, 'Includes adults aged 50-80 with a 20 pack-year history. (Pocket Medicine)'),
    (v_topic_id, '205: "Mesothelioma" is a rare cancer of the pleura strongly associated with exposure to:', '["Silica", "Asbestos", "Coal dust", "Smoking alone"]', 1, 'Smoking does NOT increase the risk of mesothelioma (unlike lung CA). (Step-Up)'),
    (v_topic_id, '206: "Bronchioloalveolar carcinoma" (now Adenocarcinoma in situ) classically presents on X-ray as a/an:', '["Solid mass", "Hazy infiltrate resembling pneumonia", "Cavity", "Nodule"]', 1, 'Presents with copious watery sputum (bronchorrhea). (Harrison''s Ch. 110)'),
    (v_topic_id, '207: What is the most common type of invasive breast cancer?', '["Lobular", "Infiltrating Ductal Carcinoma (IDC)", "Medullary", "Mucinous"]', 1, 'Presents as a hard, painless, non-mobile lump. (Step-Up)'),
    (v_topic_id, '208: BRCA1 and BRCA2 mutations increase the risk of breast cancer and which other cancer?', '["Colon", "Ovarian", "Lung", "Skin"]', 1, 'Also increases risk of male breast cancer (especially BRCA2). (Pocket Medicine)'),
    (v_topic_id, '209: "Paget Disease of the Breast" presents with nipple eczematous changes and suggests underlying:', '["Infection", "Ductal Carcinoma (DCIS or invasive)", "Allergy", "Fungus"]', 1, 'Must biopsy the nipple/areola. (Harrison''s Ch. 110)'),
    (v_topic_id, '210: "Inflammatory Breast Cancer" is a clinical diagnosis characterized by breast redness, warmth, and:', '["Fever", "Peau d''orange (skin like an orange peel)", "Discharge", "None"]', 1, 'Due to lymphatic invasion; very aggressive. (Step-Up)'),
    (v_topic_id, '211: "Tamoxifen" is used for ER-positive breast cancer and increases the risk of:', '["Lung cancer", "Endometrial cancer and Thromboembolism", "Bone loss", "Dementia"]', 1, 'Acts as an estrogen agonist in the uterus. (Pocket Medicine)'),
    (v_topic_id, '212: "Trastuzumab" (Herceptin) is used for breast cancers that overexpress:', '["Estrogen", "HER2/neu", "Progesterone", "Ki-67"]', 1, 'Can cause cardiotoxicity (requires monitoring ECHO). (Harrison''s Ch. 110)'),
    (v_topic_id, '213: "Sentinel Lymph Node Biopsy" is used to determine if breast cancer has spread to the ____ nodes.', '["Supraclavicular", "Axillary", "Inguinal", "Cervical"]', 1, 'Avoids the morbidity of full axillary dissection if negative. (Step-Up)'),
    (v_topic_id, '214: "Aromatase Inhibitors" (e.g., Anastrozole) are preferred over Tamoxifen for breast cancer in which population?', '["Pre-menopausal", "Post-menopausal", "Men", "Children"]', 1, 'They only block peripheral estrogen synthesis. (Pocket Medicine)'),
    (v_topic_id, '215: Breast cancer screening with mammography is generally recommended every 1-2 years starting at age:', '["30", "40-50", "65", "Never"]', 1, 'Guidelines vary (40 vs 50); individualize based on risk. (Harrison''s Ch. 110)'),
    (v_topic_id, '216: A "Triple Negative" breast cancer lacks ER, PR, and HER2, making it:', '["Easy to treat", "More aggressive with fewer targeted therapy options", "Benign", "None"]', 1, 'Requires standard chemotherapy. (Step-Up)'),
    (v_topic_id, '217: What is the most common type of colorectal cancer?', '["Squamous", "Adenocarcinoma", "Lymphoma", "Sarcoma"]', 1, 'Arises from adenomatous polyps. (Pocket Medicine)'),
    (v_topic_id, '218: Standard colorectal cancer screening for average-risk individuals now starts at age:', '["35", "45", "50", "60"]', 1, 'Updated recently due to rising rates in younger adults. (Harrison''s Ch. 110)'),
    (v_topic_id, '219: "Familial Adenomatous Polyposis" (FAP) is caused by a mutation in the ____ gene and carries a 100% risk of cancer.', '["p53", "APC", "KRAS", "BRAF"]', 1, 'Requires prophylactic colectomy. (Step-Up)'),
    (v_topic_id, '220: "Lynch Syndrome" (HNPCC) is due to a defect in ____ repair genes.', '["DNA mismatch", "Base excision", "Hormone", "None"]', 0, 'Increases risk of colon, endometrial, and ovarian cancers. (Pocket Medicine)'),
    (v_topic_id, '221: Left-sided colon cancers (descending/sigmoid) often present with:', E'["Anemia only", "Change in bowel habits or \\"pencil-thin\\" stools", "Weight gain", "None"]', 1, 'Due to narrower lumen and more solid stool. (Harrison''s Ch. 110)'),
    (v_topic_id, '222: Right-sided colon cancers (cecum/ascending) often present with:', '["Obstruction", "Iron deficiency anemia (occult bleeding)", "Pain", "None"]', 1, 'Lumen is larger, so tumors can grow big without obstructing. (Step-Up)'),
    (v_topic_id, '223: Which tumor marker is used to MONITOR for recurrence in colorectal cancer?', '["PSA", "CEA (Carcinoembryonic Antigen)", "AFP", "CA-125"]', 1, 'Not for screening; only for monitoring. (Pocket Medicine)'),
    (v_topic_id, '224: "Apple-core lesion" on barium enema is a classic sign of:', '["Infection", "Annular Colorectal Cancer", "Ulcer", "Diverticulitis"]', 1, 'Indicates a constricting mass. (Harrison''s Ch. 110)'),
    (v_topic_id, '225: Colorectal cancer most commonly metastasizes to which organ?', '["Bone", "Liver", "Brain", "Skin"]', 1, 'Via the portal venous system. (Step-Up)'),
    (v_topic_id, '226: "Streptococcus gallolyticus" (formerly S. bovis) bacteremia is strongly associated with underlying:', '["Diabetes", "Colon Cancer", "Lung cancer", "Heart attack"]', 1, 'Any patient with S. bovis endocarditis/bacteremia needs a colonoscopy. (Pocket Medicine)'),
    (v_topic_id, '227: "Sister Mary Joseph Nodule" is a periumbilical metastasis from which type of cancer?', '["Lung", "Gastric (Stomach)", "Skin", "Breast"]', 1, 'Classic sign of advanced intra-abdominal malignancy. (Harrison''s Ch. 110)'),
    (v_topic_id, '228: "Virchow''s Node" is a palpable left ____ lymph node suggesting abdominal cancer.', '["Axillary", "Supraclavicular", "Inguinal", "Cervical"]', 1, 'Also known as the "Troisier sign." (Step-Up)'),
    (v_topic_id, '229: What is the most common risk factor for Bladder Cancer?', '["Coffee", "Smoking", "Alcohol", "Spicy food"]', 1, 'Also occupational exposure to aniline dyes. (Pocket Medicine)'),
    (v_topic_id, '230: "Painless hematuria" in an older male smoker is ____ until proven otherwise.', '["Kidney stone", "Bladder Cancer", "UTI", "Prostatitis"]', 1, 'Requires cystoscopy and imaging. (Harrison''s Ch. 110)'),
    (v_topic_id, '231: "Renal Cell Carcinoma" (RCC) often presents with the triad of flank pain, hematuria, and:', '["Fever", "Palpable abdominal mass", "Weight gain", "Cough"]', 1, 'Classic but only seen in <10% of cases. (Step-Up)'),
    (v_topic_id, '232: "Prostate Cancer" screening is performed using DRE and ____.', '["AFP", "PSA (Prostate Specific Antigen)", "CEA", "CA-125"]', 1, 'Controversial due to overdiagnosis; discuss risks/benefits. (Pocket Medicine)'),
    (v_topic_id, '233: Prostate cancer classically metastasizes to bone, causing ____ lesions.', '["Lytic (holes)", "Blastic (bone forming)", "Mixed", "None"]', 1, 'Shows up as "hot spots" on bone scan. (Harrison''s Ch. 110)'),
    (v_topic_id, '234: "Testicular Cancer" is most common in young men and often presents as a:', '["Painful rash", "Painless solid scrotal mass", "Fever", "Hydrocele"]', 1, 'Must NOT be biopsied transscrotally (risk of seeding). (Step-Up)'),
    (v_topic_id, '235: "AFP" and "Beta-hCG" are markers for which type of cancer?', '["Prostate", "Germ Cell Tumors (Testicular/Ovarian)", "Colon", "Lung"]', 1, 'Useful for diagnosis and monitoring. (Pocket Medicine)'),
    (v_topic_id, '236: "CA-125" is a tumor marker used primarily for which cancer?', '["Breast", "Ovarian Cancer", "Lung", "Cervical"]', 1, 'Useful for monitoring response to therapy. (Harrison''s Ch. 110)'),
    (v_topic_id, '237: "Stage IV" cancer generally means the cancer has:', '["Stayed in place", "Spread to distant organs (metastasized)", "Only hit lymph nodes", "None"]', 1, 'Indicates advanced disease. (Step-Up)'),
    (v_topic_id, '238: "Performance Status" (e.g., ECOG or Karnofsky) is used to assess a patient''s:', '["Intelligence", "Ability to tolerate treatment (functional status)", "Genetic risk", "Social support"]', 1, 'Key factor in deciding between aggressive vs palliative care. (Pocket Medicine)'),
    (v_topic_id, '239: "Neutropenic Fever" is a medical emergency in oncology defined as a single temp > 38.3C and ANC < ____.', '["100", "500", "1500", "5000"]', 1, 'Requires immediate broad-spectrum IV antibiotics (e.g., Cefepime). (Harrison''s Ch. 110)'),
    (v_topic_id, '240: "Spinal Cord Compression" from metastasis presents with back pain and neurological deficits; the first step is:', '["Surgery", "High-dose IV Dexamethasone", "Radiation", "Aspirin"]', 1, 'Prevents permanent paralysis while awaiting definitive imaging (MRI). (Step-Up)'),
    (v_topic_id, '241: "Tumor Lysis Syndrome" treatment includes aggressive hydration and:', '["Insulin", "Allopurinol or Rasburicase", "Calcium", "Antibiotics"]', 1, 'To prevent uric acid-induced kidney injury. (Pocket Medicine)'),
    (v_topic_id, '242: "Hypercalcemia of Malignancy" is most commonly due to secretion of:', '["PTH", "PTHrP (PTH-related Protein)", "Vitamin D", "Calcitonin"]', 1, 'Common in squamous cell lung CA and breast CA. (Harrison''s Ch. 110)'),
    (v_topic_id, '243: "Adjuvant" therapy is given ____ primary surgery to kill micrometastases.', '["Before", "After", "During", "Instead of"]', 1, 'To reduce the risk of recurrence. (Step-Up)'),
    (v_topic_id, '244: "Neoadjuvant" therapy is given ____ primary surgery to shrink the tumor.', '["Before", "After", "During", "Never"]', 0, 'Often used in breast or rectal cancer. (Pocket Medicine)'),
    (v_topic_id, '245: "Palliative Care" aims to:', '["Cure the cancer", "Improve quality of life and manage symptoms", "Extend life at any cost", "None"]', 1, 'Appropriate at any stage of a serious illness. (Harrison''s Ch. 110)'),
    (v_topic_id, '246: "Anthracyclines" (e.g., Doxorubicin) are known for causing which specific toxicity?', '["Kidney failure", "Cardiotoxicity (dilated cardiomyopathy)", "Lung fibrosis", "Hearing loss"]', 1, 'Dose-dependent irreversible damage. (Step-Up)'),
    (v_topic_id, '247: "Acanthosis nigricans" (sudden onset in elderly) = ?', '["Diabetes", "Gastric Adenocarcinoma", "Hypothyroid", "None"]', 1, 'Paraneoplastic sign. (Pocket Medicine)'),
    (v_topic_id, '248: "Leser-Trelat sign" (sudden eruptive seborrheic keratoses) = ?', '["Aging", "Internal Malignancy (e.g., GI)", "Infection", "None"]', 1, 'Sign of an underlying cancer. (Harrison''s Ch. 110)'),
    (v_topic_id, '249: "Dermatomyositis" in an adult = ?', '["Muscle overuse", "Associated with occult malignancy (Lung, Ovary, GI)", "Vitamin deficiency", "None"]', 1, 'Paraneoplastic inflammatory myopathy. (Step-Up)'),
    (v_topic_id, '250: "Trousseau Syndrome" (migratory thrombophlebitis) = ?', '["Varicose veins", "Pancreatic Cancer", "Lung cancer", "None"]', 1, 'Hypercoagulable state of malignancy. (Pocket Medicine)'),
    (v_topic_id, '251: "Psammoma bodies" = ?', '["Papillary Thyroid CA, Serous Ovarian CA, Meningioma", "Small cell lung", "MM", "None"]', 0, 'Laminated calcified concretions. (Harrison''s Ch. 110)'),
    (v_topic_id, '252: "AFP" high = ?', '["Prostate CA", "Hepatocellular CA or Germ cell tumor", "Colon CA", "None"]', 1, 'Liver cancer or yolk sac tumor. (Step-Up)'),
    (v_topic_id, '253: "CA-19-9" = ?', '["Breast", "Pancreatic Cancer", "Lung", "None"]', 1, 'Used to monitor pancreatic cancer therapy. (Pocket Medicine)'),
    (v_topic_id, '254: "CEA" = ?', '["Ovary", "Colorectal Cancer", "Prostate", "None"]', 1, 'Used to monitor colon cancer. (Harrison''s Ch. 110)'),
    (v_topic_id, '255: "PSA" = ?', '["Bladder", "Prostate Cancer", "Kidney", "None"]', 1, 'Prostate specific antigen. (Step-Up)'),
    (v_topic_id, '256: "Bleomycin" toxicity = ?', '["Heart", "Pulmonary Fibrosis", "Kidney", "Nerves"]', 1, 'Check PFTs before use. (Pocket Medicine)'),
    (v_topic_id, '257: "Cisplatin" toxicity = ?', '["Ototoxicity and Nephrotoxicity", "Liver", "Lungs", "None"]', 0, 'Prevent kidney damage with fluids/amifostine. (Harrison''s Ch. 110)'),
    (v_topic_id, '258: "Vincristine" toxicity = ?', '["Diarrhea", "Peripheral Neuropathy", "Heart failure", "None"]', 1, '"V"incristine = "V"ery bad for nerves. (Step-Up)'),
    (v_topic_id, '259: "Cyclophosphamide" toxicity = ?', '["Lung", "Hemorrhagic Cystitis", "Liver", "None"]', 1, 'Prevent with MESNA and hydration. (Pocket Medicine)'),
    (v_topic_id, '260: "5-FU" and "Methotrexate" side effect = ?', '["Bone fracture", "Mucositis/Stomatitis", "Rash", "None"]', 1, 'Oral ulcers and GI upset. (Harrison''s Ch. 110)'),
    (v_topic_id, '261: "S-100" marker = ?', '["Melanoma", "Colon CA", "Lung CA", "None"]', 0, 'Marker for neural crest-derived cells. (Step-Up)'),
    (v_topic_id, '262: "Etoposide" side effect = ?', '["Alopecia", "Second Malignancies (AML)", "Heart failure", "None"]', 1, 'Risk of topoisomerase inhibitor therapy. (Pocket Medicine)'),
    (v_topic_id, '263: "Paclitaxel" toxicity = ?', '["Hypersensitivity and Peripheral neuropathy", "Liver", "Kidney", "None"]', 0, 'Requires premedication with steroids/antihistamines. (Harrison''s Ch. 110)'),

    -- SECTION 24-28: FINAL SPRINT
    (v_topic_id, '264: What is the most common type of skin cancer?', '["Squamous Cell", "Basal Cell Carcinoma", "Melanoma", "Merkel Cell"]', 1, 'Presents as a pearly papule with telangiectasias. (Harrison''s Ch. 110)'),
    (v_topic_id, '265: Which skin cancer is most likely to metastasize and cause death?', '["Basal Cell", "Malignant Melanoma", "Squamous Cell", "Actinic Keratosis"]', 1, 'Prognosis depends on the "Breslow depth" (thickness). (Step-Up)'),
    (v_topic_id, '266: The "ABCD" of melanoma screening stands for Asymmetry, Border irregularity, Color variegation, and:', '["Depth", "Diameter > 6mm", "Density", "Duration"]', 1, 'Helps identify suspicious lesions. (Pocket Medicine)'),
    (v_topic_id, '267: "Squamous Cell Carcinoma" of the skin is most common in sun-exposed areas and often arises from:', '["Mols", "Actinic Keratoses", "Scars", "None"]', 1, 'Actinic Keratosis is a pre-cancerous lesion. (Harrison''s Ch. 110)'),
    (v_topic_id, '268: "Kaposi Sarcoma" is associated with which virus?', '["EBV", "HHV-8", "HIV alone", "HPV"]', 1, 'Presents as purple/red nodules in immunocompromised patients. (Step-Up)'),
    (v_topic_id, '269: "Angiosarcoma" of the arm is a rare but classic complication after chronic lymphedema (e.g., post-mastectomy), known as:', '["Stewart-Treves Syndrome", "Marjolin ulcer", "Gardner syndrome", "None"]', 0, 'Aggressive vascular tumor. (Pocket Medicine)'),
    (v_topic_id, '270: "Osteosarcoma" classically presents with which radiographic finding?', '["Onion skinning", "Sunburst pattern / Codman triangle", "Lytic holes", "None"]', 1, 'Most common primary bone tumor in young adults. (Harrison''s Ch. 110)'),
    (v_topic_id, '271: "Ewing Sarcoma" is associated with the t(11;22) translocation and which X-ray finding?', '["Sunburst", "Onion-skin periosteal reaction", "Soap bubble", "None"]', 1, 'Small round blue cell tumor. (Step-Up)'),
    (v_topic_id, '272: "Li-Fraumeni Syndrome" is due to a germline mutation in ____ and leads to early-onset sarcomas and breast cancer.', '["p53", "Rb", "APC", "WT1"]', 0, 'Guardian of the genome. (Pocket Medicine)'),
    (v_topic_id, '273: "Retinoblastoma" is associated with a mutation in the ____ gene.', '["p53", "RB1", "NF1", "VHL"]', 1, 'Classic example of the "Two-hit hypothesis." (Harrison''s Ch. 110)'),
    (v_topic_id, '274: "Rituximab" is a monoclonal antibody that targets:', '["HER2", "CD20", "VEGF", "PD-1"]', 1, 'Used in B-cell lymphomas and CLL. (Step-Up)'),
    (v_topic_id, '275: "Bevacizumab" (Avastin) works by inhibiting:', '["Tyrosine kinase", "VEGF (angiogenesis)", "mTOR", "Proteasome"]', 1, 'Can cause side effects like hypertension and bleeding. (Pocket Medicine)'),
    (v_topic_id, '276: "Pembrolizumab" and "Nivolumab" are checkpoint inhibitors that target:', '["CD20", "PD-1 / PD-L1", "CTLA-4", "HER2"]', 1, 'Releases the "brakes" on the immune system to attack cancer. (Harrison''s Ch. 110)'),
    (v_topic_id, '277: "Imatinib" (Gleevec) targets which fusion protein?', '["p53", "BCR-ABL", "c-MYC", "None"]', 1, 'Selective tyrosine kinase inhibitor. (Step-Up)'),
    (v_topic_id, '278: "Bortezomib" is a ____ inhibitor used to treat Multiple Myeloma.', '["Tyrosine kinase", "Proteasome", "VEGF", "Checkpoint"]', 1, 'Inhibits degradation of pro-apoptotic proteins. (Pocket Medicine)'),
    (v_topic_id, '279: "Erlotinib" and "Gefitinib" are used in lung cancer patients with ____ mutations.', '["ALK", "EGFR", "KRAS", "BRAF"]', 1, 'More common in non-smokers and women. (Harrison''s Ch. 110)'),
    (v_topic_id, '280: "Vemurafenib" is used for advanced melanoma with which mutation?', '["NRAS", "BRAF V600E", "p53", "None"]', 1, 'Specific for the mutated kinase. (Step-Up)'),
    (v_topic_id, '281: Immune-related side effects of checkpoint inhibitors (like colitis or pneumonitis) are treated with:', '["More chemo", "Glucocorticoids (Steroids)", "Antibiotics", "None"]', 1, 'Required to suppress the overactive immune response. (Pocket Medicine)'),
    (v_topic_id, '282: "Lapatinib" is a dual inhibitor of HER2 and ____.', '["VEGF", "EGFR", "ALK", "PD-1"]', 1, 'Used in breast cancer. (Harrison''s Ch. 110)'),
    (v_topic_id, '283: "Denosumab" (Xgeva) is used in oncology to prevent:', '["Infection", "Skeletal-related events (fractures) from bone metastases", "Nausea", "None"]', 1, 'Blocks RANK Ligand. (Step-Up)'),
    (v_topic_id, '284: "Kallmann Syndrome" = ?', '["Anosmia + Hypogonadism", "Blindness", "Deafness", "None"]', 0, 'Failure of GnRH neurons to migrate. (Pocket Medicine)'),
    (v_topic_id, '285: "Fanconi Anemia" = ?', '["Short stature + Thumb defects + Aplastic Anemia", "Long limbs", "Large ears", "None"]', 0, 'DNA repair defect. (Harrison''s Ch. 98)'),
    (v_topic_id, '286: "Diamond-Blackfan Anemia" = ?', '["Pancytopenia", "Pure Red Cell Aplasia in an infant", "Iron overload", "None"]', 1, 'Congenital erythroid failure. (Step-Up)'),
    (v_topic_id, '287: "Schwabach test" compares bone conduction of the patient to:', '["The examiner", "Air conduction", "A computer", "None"]', 0, 'Old audiometric test. (Pocket Medicine)'),
    (v_topic_id, '288: "Wiskott-Aldrich Syndrome" triad: Eczema, Immunodeficiency, and:', '["Large platelets", "Small platelets (Thrombocytopenia)", "Anemia", "None"]', 1, '"TIE" = Thrombocytopenia, Infections, Eczema. (Harrison''s Ch. 110)'),
    (v_topic_id, '289: "Job Syndrome" (Hyper-IgE) presents with "cold" abscesses and:', '["High IgG", "High IgE and Eosinophilia", "High IgA", "None"]', 1, '"FATED" = Facies, Abscesses, Teeth, IgE, Dermatological. (Step-Up)'),
    (v_topic_id, '290: "DiGeorge Syndrome" (22q11.2 deletion) involves which branchial pouches?', '["1st and 2nd", "3rd and 4th", "5th", "None"]', 1, '"CATCH-22" = Cardiac, Abnormal facies, Thymic hypoplasia, Cleft palate, Hypocalcemia. (Pocket Medicine)'),
    (v_topic_id, '291: "Bruton Agammaglobulinemia" is a deficiency of which enzyme?', '["ADA", "BTK (Bruton Tyrosine Kinase)", "G6PD", "None"]', 1, 'X-linked; failure of B-cell maturation. (Harrison''s Ch. 110)'),
    (v_topic_id, '292: "Chronic Granulomatous Disease" (CGD) is a defect in ____, leading to infections with catalase-positive organisms.', '["Antibodies", "NADPH oxidase (oxidative burst)", "Complement", "T-cells"]', 1, 'Diagnosed with DHR flow cytometry. (Step-Up)'),
    (v_topic_id, '293: "Catalase-positive" organisms include S. aureus, Aspergillus, and ____.', '["Streptococcus", "Serratia and Burkholderia", "E. coli only", "None"]', 1, 'Important for CGD patients. (Pocket Medicine)'),
    (v_topic_id, '294: "Auer rods" = ?', '["AML", "ALL", "CLL", "CML"]', 0, 'Myeloblast granules. (Harrison''s Ch. 110)'),
    (v_topic_id, '295: "Smudge cells" = ?', '["ALL", "CLL", "CML", "AML"]', 1, 'Fragile CLL lymphocytes. (Step-Up)'),
    (v_topic_id, '296: "Reed-Sternberg cells" = ?', '["NHL", "Hodgkin Lymphoma", "MM", "None"]', 1, 'Pathognomonic B-cells. (Pocket Medicine)'),
    (v_topic_id, '297: "Philadelphia chromosome" t(9;22) = ?', '["AML", "CML", "ALL", "None"]', 1, 'BCR-ABL fusion. (Harrison''s Ch. 110)'),
    (v_topic_id, '298: "t(15;17)" = ?', '["Burkitt", "APL (AML M3)", "Follicular", "Mantle"]', 1, 'Responds to ATRA. (Step-Up)'),
    (v_topic_id, '299: "t(8;14)" = ?', '["Burkitt Lymphoma", "Follicular", "Mantle", "None"]', 0, 'c-MYC activation. (Pocket Medicine)'),
    (v_topic_id, '300: "t(14;18)" = ?', '["Burkitt", "Follicular Lymphoma", "Mantle", "None"]', 1, 'BCL-2 activation. (Harrison''s Ch. 110)'),
    (v_topic_id, '301: "t(11;14)" = ?', '["Follicular", "Mantle Cell Lymphoma", "Burkitt", "None"]', 1, 'Cyclin D1 activation. (Step-Up)'),
    (v_topic_id, '302: "JAK2 V617F" = ?', '["CML", "Polycythemia Vera / ET / Myelofibrosis", "AML", "None"]', 1, 'Myeloproliferative marker. (Pocket Medicine)'),
    (v_topic_id, '303: "BRAF V600E" = ?', '["Colon CA", "Melanoma", "Lung CA", "None"]', 1, 'Target for Vemurafenib. (Harrison''s Ch. 110)'),
    (v_topic_id, '304: "HER2/neu" = ?', '["Ovarian CA", "Breast Cancer", "Colon CA", "None"]', 1, 'Target for Trastuzumab. (Step-Up)'),
    (v_topic_id, '305: "ALK" translocation = ?', '["Breast CA", "Non-Small Cell Lung Cancer (Adeno)", "Prostate", "None"]', 1, 'Target for Crizotinib. (Pocket Medicine)'),
    (v_topic_id, '306: "S-100" = ?', '["Lung", "Melanoma", "Prostate", "None"]', 1, 'Neural crest marker. (Harrison''s Ch. 110)'),
    (v_topic_id, '307: "TRAP positive" = ?', '["CLL", "Hairy Cell Leukemia", "ALL", "None"]', 1, 'Tartrate-resistant acid phosphatase. (Step-Up)'),
    (v_topic_id, '308: "TdT positive" = ?', '["AML", "ALL", "CML", "None"]', 1, 'Lymphoblast marker. (Pocket Medicine)'),
    (v_topic_id, '309: "CD15 and CD30" = ?', '["NHL", "Hodgkin Lymphoma", "CLL", "None"]', 1, 'Classic HL markers. (Harrison''s Ch. 110)'),
    (v_topic_id, '310: "CD19 and CD20" = ?', '["T-cells", "B-cells", "Platelets", "None"]', 1, 'B-cell lineage markers. (Step-Up)'),
    (v_topic_id, '311: "CD3 and CD4/CD8" = ?', '["B-cells", "T-cells", "Neutrophils", "None"]', 1, 'T-cell lineage markers. (Pocket Medicine)'),
    (v_topic_id, '312: "Hypersegmented neutrophils" = ?', '["Iron deficiency", "B12 / Folate deficiency", "Lead poisoning", "None"]', 1, 'Megaloblastic anemia. (Harrison''s Ch. 95)'),
    (v_topic_id, '313: "Schistocytes" = ?', '["Sickle cell", "MAHA (TTP/HUS/DIC)", "Spherocytosis", "None"]', 1, 'Mechanical fragmentation. (Step-Up)'),
    (v_topic_id, '314: "Bite cells" = ?', '["Thalassemia", "G6PD Deficiency", "Sickle cell", "None"]', 1, 'Splenic pitting of Heinz bodies. (Pocket Medicine)'),
